// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Arrays;
import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.common.order.StatementOrder;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVectors.BranchRole;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.junit.jupiter.api.Test;

/**
 * The factorized row join prices a branch per distinct probe key (its executor memoises the branch result per key),
 * counts and existence checks without decoding values, and emits one batch row per logical output row.
 */
class LmdbNativeFactorizedQuoteTest {

	private static final long P1 = 1L, P2 = 2L;
	private static final int S = 0, A = 1, B = 2;

	/** Every binding mask is fully covered by an index, so a probe is one seek over its own rows. */
	private static NativeLmdbQuerySource.IndexAccessProfile coveringProfile(long entries) {
		int[][] prefixes = new int[StatementOrder.values().length + 1][16];
		for (int[] row : prefixes) {
			for (int mask = 0; mask < 16; mask++) {
				row[mask] = Integer.bitCount(mask);
			}
		}
		return new NativeLmdbQuerySource.IndexAccessProfile(entries, 1, prefixes, false, -1L, -1L, -1L);
	}

	private static PatternPlan star(long predicate, int objectSlot, double staticEstimate) {
		return new PatternPlan(Term.slot(S), Term.constant(predicate), Term.slot(objectSlot), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, staticEstimate, coveringProfile(100_000L));
	}

	private static RowState row(NativeLmdbQuerySource source) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("s", S, "a", A, "b", B), null);
		layout.freeze(List.of("s", "a", "b"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, LmdbNativeAggregateCompiler.UNKNOWN);
		row.recomputeBoundMask();
		return row;
	}

	private static StatsSource stats() {
		return new StatsSource(100_000L).predicate(P1, 3D, 3_000L).predicate(P2, 3D, 3_000L);
	}

	private static LmdbNativeCostVector quote(BranchRole role, double depth0Keys) {
		SlotPlan[] order = { star(P1, A, 9_000D), star(P2, B, 9_000D) };
		return LmdbNativeCostVectors.factorizedRows(order, 1, new BranchRole[] { role }, depth0Keys, row(stats()),
				0L);
	}

	private static LmdbNativeCostVector probe() {
		// one probe of ?s p2 ?b with ?s bound: its seeks, scanned and decoded rows
		return LmdbNativeCostVectors.pattern(star(P2, B, 9_000D), row(stats()), 1L << S);
	}

	private static LmdbNativeCostVector prefix() {
		return LmdbNativeCostVectors.pattern(star(P1, A, 9_000D), row(stats()), 0L);
	}

	@Test
	void aCountingBranchIsSeekedOncePerDistinctKey() {
		LmdbNativeCostVector quote = quote(BranchRole.COUNT, Double.NaN);
		// 9000 prefix rows carry 3000 distinct subjects: 3000 probes expected, one per prefix row at worst
		assertThat(quote.expected(Feature.INDEX_SEEK))
				.isEqualTo(prefix().expected(Feature.INDEX_SEEK) + 3_000D * probe().expected(Feature.INDEX_SEEK));
		assertThat(quote.high(Feature.INDEX_SEEK))
				.isGreaterThanOrEqualTo(prefix().high(Feature.INDEX_SEEK) + 9_000D * probe().high(Feature.INDEX_SEEK));
	}

	@Test
	void aCountingBranchChargesNoBatchRowPerBranchRowAndNoDecode() {
		LmdbNativeCostVector quote = quote(BranchRole.COUNT, Double.NaN);
		// a batch row per prefix row and one per emitted row (the count becomes the row's multiplicity): no 27000
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(9_000D + 9_000D);
		// counting never decodes the branch's values: only the prefix decodes
		assertThat(quote.expected(Feature.DECODED_ROW)).isEqualTo(prefix().expected(Feature.DECODED_ROW));
		// the memo is consulted once per prefix row
		assertThat(quote.expected(Feature.HASH_PROBE)).isEqualTo(9_000D);
	}

	@Test
	void anEnumBranchChargesBatchPerBranchRowPerKeyAndPerEmittedRow() {
		LmdbNativeCostVector quote = quote(BranchRole.ENUM, Double.NaN);
		// 3000 keys × 3 rows materialised once each, then 9000 × 3 rows emitted
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(9_000D + 3_000D * 3D + 27_000D);
		assertThat(quote.expected(Feature.DECODED_ROW))
				.isEqualTo(prefix().expected(Feature.DECODED_ROW) + 3_000D * probe().expected(Feature.DECODED_ROW));
	}

	@Test
	void anExistsBranchReadsOneRecordPerKey() {
		LmdbNativeCostVector quote = quote(BranchRole.EXISTS, Double.NaN);
		assertThat(quote.expected(Feature.SCANNED_ROW)).isEqualTo(prefix().expected(Feature.SCANNED_ROW) + 3_000D);
		assertThat(quote.expected(Feature.DECODED_ROW)).isEqualTo(prefix().expected(Feature.DECODED_ROW));
	}

	@Test
	void theKeysOnlyRootCapsDepthZeroRows() {
		LmdbNativeCostVector quote = quote(BranchRole.COUNT, 3_000D);
		// the root walks 3000 keys without decoding a run, and the branch is probed at most 3000 times
		assertThat(quote.expected(Feature.DECODED_ROW)).isZero();
		assertThat(quote.expected(Feature.SCANNED_ROW)).isGreaterThanOrEqualTo(3_000D);
		assertThat(quote.high(Feature.INDEX_SEEK)).isLessThanOrEqualTo(1D + 3_000D * probe().high(Feature.INDEX_SEEK));
	}

	@Test
	void anUnpriceableBranchKeepsTheSweepCeiling() {
		SlotPlan unpriced = new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				throw new UnsupportedOperationException();
			}

			@Override
			public long producedMask() {
				return 1L << B;
			}
		};
		SlotPlan[] order = { star(P1, A, 9_000D), unpriced };
		LmdbNativeCostVector quote = LmdbNativeCostVectors.factorizedRows(order, 1,
				new BranchRole[] { BranchRole.COUNT }, Double.NaN, row(stats()), 0L);
		assertThat(quote.high(Feature.SCANNED_ROW)).isGreaterThanOrEqualTo(9_000D * 100_000D);
	}
}
